CREATE TABLE "TeamAvailability" ("id" TEXT NOT NULL,"teamId" TEXT NOT NULL,"userId" TEXT NOT NULL,"weekStart" TIMESTAMP(3) NOT NULL,"capacityPoints" INTEGER NOT NULL,"reason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TeamAvailability_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TeamHoliday" ("id" TEXT NOT NULL,"teamId" TEXT NOT NULL,"date" TIMESTAMP(3) NOT NULL,"name" TEXT NOT NULL,"capacityReductionPoints" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "TeamHoliday_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PlanAllocation" ("id" TEXT NOT NULL,"planId" TEXT NOT NULL,"issueId" TEXT NOT NULL,"teamId" TEXT NOT NULL,"weekStart" TIMESTAMP(3) NOT NULL,"estimatePoints" INTEGER NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PlanAllocation_pkey" PRIMARY KEY ("id"));
